/**
 * Get recommended Aniimo for a given ability and level requirement.
 * @param {string} ability - Ability name (e.g. 'Fire', 'Water', 'Artisanship')
 * @param {number} minLevel - Minimum level required
 * @param {boolean} preferPrismana - Whether to prioritize Lv.4 Prismana
 * @returns {{ primary: object, alternatives: object[], ability: string, level: number, isPrismana: boolean }}
 */
export function getRecommendedWorker(ability, minLevel = 1, preferPrismana = true) {
    const pool = ABILITY_WORKERS[ability];
    if (!pool) {
        return null;
    }

    let primary = null;
    let alternatives = [];

    // CRITICAL: Luôn ưu tiên dùng Aniimo có cấp độ gia viên cao nhất, tránh đề xuất cấp 1, 2!
    // 1. Ưu tiên số 1: Prismana Lv.4 (cấp cao nhất trong game cho mọi công việc)
    if (pool.prismana_lv4 && pool.prismana_lv4.length > 0) {
        // Lọc unique các loài Prismana theo tên và sort theo base_level giảm dần
        const seenNames = new Set();
        const uniquePrismana = [];
        for (const w of pool.prismana_lv4) {
            if (!seenNames.has(w.name)) {
                seenNames.add(w.name);
                uniquePrismana.push({ ...w, is_prismana: true, level: 4 });
            }
        }
        uniquePrismana.sort((a, b) => (b.base_level || 0) - (a.base_level || 0));

        primary = uniquePrismana[0];

        // Các loài Prismana khác ngoài primary
        const altPrismana = uniquePrismana.slice(1);

        // Các loài tự nhiên Cấp 3 (chưa từng có trong danh sách Prismana ở trên)
        const altNormal3 = [];
        for (const w of (pool.normal_lv3 || [])) {
            if (!seenNames.has(w.name)) {
                seenNames.add(w.name);
                altNormal3.push({ ...w, is_prismana: false, level: Math.min(3, w.base_level || 3) });
            }
        }

        // Gộp lại danh sách thay thế, đảm bảo 100% không trùng tên
        alternatives = [...altPrismana, ...altNormal3].slice(0, 5);
        return {
            primary,
            alternatives,
            ability,
            level: 4,
            isPrismana: true
        };
    }

    // 2. Ưu tiên số 2: Gốc Lv.3 (cho các hệ không có Prismana như Quang/Light, Điều Hương/Perfumery)
    if (pool.normal_lv3 && pool.normal_lv3.length > 0) {
        const seenNames = new Set();
        const uniqueNormal3 = [];
        for (const w of pool.normal_lv3) {
            if (!seenNames.has(w.name)) {
                seenNames.add(w.name);
                uniqueNormal3.push({ ...w, is_prismana: false, level: Math.min(3, w.base_level || 3) });
            }
        }
        primary = uniqueNormal3[0];
        alternatives = uniqueNormal3.slice(1, 5);
        return {
            primary,
            alternatives,
            ability,
            level: 3,
            isPrismana: false
        };
    }

    // 3. Fallback cấp thấp chỉ khi hệ không có cả Lv.4 lẫn Lv.3 (tránh tối đa cấp 1, 2)
    if (pool.normal_lv2 && pool.normal_lv2.length > 0) {
        const seenNames = new Set();
        const uniqueNormal2 = [];
        for (const w of pool.normal_lv2) {
            if (!seenNames.has(w.name)) {
                seenNames.add(w.name);
                uniqueNormal2.push({ ...w, is_prismana: false, level: Math.min(2, w.base_level || 2) });
            }
        }
        primary = uniqueNormal2[0];
        alternatives = uniqueNormal2.slice(1, 5);
        return {
            primary,
            alternatives,
            ability,
            level: 2,
            isPrismana: false
        };
    }

    const seenNames = new Set();
    const uniqueNormal1 = [];
    for (const w of (pool.normal_lv1 || [])) {
        if (!seenNames.has(w.name)) {
            seenNames.add(w.name);
            uniqueNormal1.push({ ...w, is_prismana: false, level: 1 });
        }
    }
    primary = uniqueNormal1[0] || null;
    alternatives = uniqueNormal1.slice(1, 5);
    return {
        primary,
        alternatives,
        ability,
        level: 1,
        isPrismana: false
    };
}

/**
 * Get specific worker for exact level (1, 2, 3, 4) in roster preview.
 * @param {string} ability
 * @param {number} level
 * @returns {object|null}
 */
export function getWorkerForLevel(ability, level) {
    const pool = ABILITY_WORKERS[ability];
    if (!pool) return null;
    if (level >= 4) {
        return pool.prismana_lv4[0] || pool.normal_lv3[0] || null;
    }
    if (level === 3) {
        return pool.normal_lv3[0] || pool.prismana_lv4[0] || null;
    }
    if (level === 2) {
        return pool.normal_lv2[0] || pool.normal_lv3[0] || null;
    }
    return pool.normal_lv1[0] || pool.normal_lv2[0] || pool.normal_lv3[0] || null;
}

/**
/**
 * Resident facilities that strictly require a specific Aniimo.
 * - Nhà sương mai (Dewy House): Fragrancier
 * - Giường mây (Nimbus Bed): Turbo
 * - Lâu đài cát cấp 2 (Tidewhisper Sandcastle Lv.2): Panpanta
 * - Lâu đài cát cấp 3 (Tidewhisper Sandcastle Lv.3): Sherro
 * - Võng sao (Starfall Hammock): Stellarys
 */
export function getFacilitySpecificWorker(facility, itemName = '', facilityLevel = 1) {
    if (!facility) return null;
    const fac = facility.replace(/ \(Manual\)$/, '').replace(/ \(Electric\)$/, '').trim();
    if (fac === 'Dewy House' || fac === 'Nhà Dewy' || fac === 'Nhà sương mai') return 'Fragrancier';
    if (fac === 'Nimbus Bed' || fac === 'Giường Cỏ Mây' || fac === 'Giường mây' || fac === 'Giường mây Nimbus') return 'Turbo';
    if (fac === 'Tidewhisper Sandcastle' || fac === 'Lâu Đài Cát Thủy Triều Thì Thầm' || fac === 'Lâu đài cát' || fac === 'Lâu đài cát Tidewhisper') {
        if (itemName === 'pearl' || (facilityLevel && facilityLevel >= 3)) return 'Sherro';
        if (itemName === 'quick_sea_salt' || (facilityLevel && facilityLevel >= 2)) return 'Panpanta';
        return 'Panpanta';
    }
    if (fac === 'Starfall Hammock' || fac === 'Võng Sao Rơi' || fac === 'Võng sao Starfall') return 'Stellarys';
    return null;
}

/**
 * Render an individual Aniimo worker avatar card with badge and rich tooltip.
 * Luôn đề xuất Aniimo có cấp độ cao nhất (Prismana Lv.4 hoặc Lv.3), tránh đề xuất cấp 1, 2.
 * @param {string} ability - Ability name
 * @param {number} minLevel - Work min level required
 * @param {string} note - Optional bonus note (e.g. personality bonus)
 * @param {boolean} compact - Compact mode for multi-worker tasks
 * @param {string} specificName - Optional specific Aniimo name override
 * @returns {string} HTML markup
 */
export function renderAniimoWorkerCard(ability, minLevel = 1, note = '', compact = false, specificName = '') {
    let worker = null;
    let isPrismana = false;
    let workerLevel = typeof minLevel === 'number' ? minLevel : 3;
    let alternatives = [];

    if (specificName) {
        const found = ANIIMO_DB.find(a => a.name.toLowerCase() === specificName.toLowerCase());
        if (found) {
            const ab = found.abilities.find(a => a.ability_en === ability) || found.abilities[0];
            isPrismana = found.is_prismana && ((ab?.prismana_level || 0) >= 4);
            workerLevel = isPrismana ? (ab?.prismana_level || 4) : Math.min(3, ab?.base_level || 3);
            worker = found;
        }
    }

    if (!worker) {
        const rec = getRecommendedWorker(ability, minLevel, true);
        if (rec && rec.primary) {
            worker = rec.primary;
            isPrismana = rec.isPrismana;
            workerLevel = rec.level;
            alternatives = rec.alternatives || [];
        }
    }

    const theme = ABILITY_THEMES[ability] || { color: '#888888', icon: '🐾', vi: ability };
    const isVi = window.i18n && window.i18n.getLang() === 'vi';
    const abilityDisplay = isVi ? theme.vi : ability;

    if (!worker) {
        return `<span class="ability-dot" style="--ability:${theme.color}">${minLevel}</span>`;
    }
    
    // Construct rich tooltip
    const altsText = alternatives.length > 0
        ? (isVi ? `Đề xuất khác / thay thế: ${alternatives.map(a => a.name + (a.is_prismana ? ' (Prismana Lv.4)' : ` (Lv.${Math.min(3, a.base_level || 3)})`)).join(', ')}` 
                : `Other options / alternatives: ${alternatives.map(a => a.name + (a.is_prismana ? ' (Prismana Lv.4)' : ` (Lv.${Math.min(3, a.base_level || 3)})`)).join(', ')}`)
        : '';
    
    const reqNote = (typeof minLevel === 'number' && minLevel < workerLevel)
        ? (isVi ? ` (Yêu cầu tối thiểu của việc: Lv.${minLevel})` : ` (Task min required: Lv.${minLevel})`)
        : '';

    const tipTitle = `${worker.name} · ${abilityDisplay} Lv.${workerLevel}${isPrismana ? ' (Prismana)' : ''}${reqNote}`;
    const tipBody = [
        tipTitle,
        note ? `• ${note}` : '',
        altsText ? `• ${altsText}` : ''
    ].filter(Boolean).join('\n');

    const cardClass = `aniimo-worker-card ${compact ? 'compact' : ''} ${isPrismana ? 'is-prismana' : ''}`;

    return `
        <div class="${cardClass}" style="--ability-color:${theme.color}" title="${tipBody}" aria-label="${tipTitle}">
            <div class="aniimo-avatar-wrap">
                <img class="aniimo-avatar-img" src="${worker.img_url}" alt="${worker.name}" loading="lazy" onerror="this.src='https://aniimoguide.com/images/aniimo/head_round/${worker.number || '10011'}.webp'">
                <span class="aniimo-level-badge ${isPrismana ? 'prismana-badge' : ''}">${workerLevel}</span>
            </div>
            ${!compact ? `<span class="aniimo-worker-name">${worker.name}</span>` : ''}
        </div>
    `;
}

/**
 * Render a cluster of Aniimo workers (for multi-task facilities like Farmland).
 * @param {Array<{ability: string, level: number, personality_bonus?: boolean}>} tasks
 * @param {string} facilityName
 * @returns {string} HTML markup
 */
export function renderAniimoTasksCluster(tasks, facilityName) {
    if (!tasks || tasks.length === 0) return '-';
    const isVi = window.i18n && window.i18n.getLang() === 'vi';
    
    const items = tasks.map(task => {
        let note = '';
        if (task.personality_bonus) {
            note = isVi ? 'Tính cách tương thích (+20% tốc độ)' : 'Matching personality (+20% speed)';
        }
        return renderAniimoWorkerCard(task.ability, task.level, note, true);
    });

    return `<div class="aniimo-cluster">${items.join('')}</div>`;
}

/**
 * Render a compact avatar badge for the Roster/Team display.
 * Luôn ưu tiên công nhân cấp cao nhất.
 * @param {string} ability
 * @param {number|string} level
 * @param {number} count
 * @param {string} tip
 * @param {boolean} bonus
 * @param {string} specificName
 * @returns {string}
 */
export function renderRosterWorkerBadge(ability, level, count = 1, tip = '', bonus = false, specificName = '') {
    let worker = null;
    let isPrismana = true;
    let workerLevel = 4;

    if (specificName) {
        const found = ANIIMO_DB.find(a => a.name.toLowerCase() === specificName.toLowerCase());
        if (found) {
            const ab = found.abilities.find(a => a.ability_en === ability) || found.abilities[0];
            isPrismana = found.is_prismana && ((ab?.prismana_level || 0) >= 4);
            workerLevel = isPrismana ? (ab?.prismana_level || 4) : Math.min(3, ab?.base_level || 3);
            worker = found;
        }
    }

    if (!worker) {
        const rec = getRecommendedWorker(ability, 4, true);
        worker = rec ? rec.primary : null;
        isPrismana = rec ? rec.isPrismana : true;
        workerLevel = rec ? rec.level : 4;
    }

    const theme = ABILITY_THEMES[ability] || { color: '#888888', icon: '🐾', vi: ability };
    const times = count > 1 ? `<span class="ability-times">×${count}</span>` : '';
    
    if (!worker) {
        return `<span class="ability-kind"><span class="ability-dot small${bonus ? ' bonus' : ''}" style="--ability:${theme.color}" title="${tip}">${workerLevel}</span>${times}</span>`;
    }

    const fullTip = tip ? `${worker.name} (${theme.vi} Lv.${workerLevel}${isPrismana ? ' Prismana' : ''})${bonus ? ' (+20% tốc độ)' : ''} · ${tip}` : `${worker.name} · ${theme.vi} Lv.${workerLevel}`;

    return `
        <span class="roster-worker-item ${isPrismana ? 'is-prismana' : ''}" style="--ability-color:${theme.color}" title="${fullTip}">
            <span class="roster-avatar-wrap">
                <img class="roster-avatar-img" src="${worker.img_url}" alt="${worker.name}" loading="lazy" onerror="this.src='https://aniimoguide.com/images/aniimo/head_round/${worker.number || '10011'}.webp'">
                <span class="roster-level-badge ${isPrismana ? 'prismana-badge' : ''}">${workerLevel}</span>
            </span>
            ${times}
        </span>
    `;
}

